local chvpr
do
  local zft, ofucp = pcall(function() return bit32 end)
  if zft and ofucp and ofucp.bxor then
    chvpr = function(znuxs, eec) return ofucp.bxor(znuxs, eec) % 256 end
  else
    chvpr = function(znuxs, eec)
      local nxec, cfowh = 0, 1
      while znuxs > 0 or eec > 0 do
        local lebo, tzmjv = znuxs % 2, eec % 2
        if lebo ~= tzmjv then nxec = nxec + cfowh end
        znuxs = (znuxs - lebo) / 2
        eec = (eec - tzmjv) / 2
        cfowh = cfowh * 2
      end
      return nxec
    end
  end
end
